const certCard=(c,i)=>`<article class="cert" data-ci="${i}"><button type="button" class="cert-open" data-c="${i}" aria-label="View certificate: ${esc(c.title)}"></button><div class="th"><img src="${IMG.thumbs[c.img]}" alt="" loading="lazy"></div><div class="meta"><h3>${esc(c.title)}</h3><span class="iss">${ISS[c.issuer]?`<img class="iss-logo" src="${ISS[c.issuer]}" alt="" width="26" height="26">`:''}<span>${esc(c.issuer)}</span></span>${c.desc?`<p class="cert-desc">${esc(c.desc)}</p>`:''}<span class="dt"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/></svg>${c.date}</span></div></article>`;
