let filter='All';
function renderCerts(){const cats=['All','Course','Training','Webinar'];
 {const btn=c=>`<button type="button" data-f="${c}" aria-pressed="${c===filter}">${c} <span class="pf-n">${c==='All'?D.certs.length:D.certs.filter(x=>x.cat===c).length}</span></button>`;$('#filters').innerHTML=cats.map(btn).join('');}
 $('#allCerts').innerHTML=D.certs.map((c,i)=>(filter==='All'||c.cat===filter)?certCard(c,i):'').join('')}
$('#filters').onclick=e=>{const b=e.target.closest('button');if(!b||b.dataset.f===filter)return;filter=b.dataset.f;
 const box=$('#allCerts'),still=matchMedia('(prefers-reduced-motion: reduce)').matches;box.classList.add('leaving');
 setTimeout(()=>{renderCerts();box.classList.remove('leaving');
  if(!still)box.querySelectorAll('.cert').forEach((c,i)=>{c.style.setProperty('--pd',(Math.min(i,8)*.06)+'s');c.classList.add('pop');c.addEventListener('animationend',()=>c.classList.remove('pop'),{once:true})});
  RV.scan()},still?0:180)};
renderCerts();

/* lightbox */
let lastFocus=null;
function openLb(img,title,meta,file){lastFocus=document.activeElement;const full=(window.FULL||{})[img]||IMG.thumbs[img]||'';$('#lbImg').src=full;$('#lbImg').alt=title;$('#lbTitle').textContent=title;$('#lbMeta').textContent=meta;$('#lbLink').href=file;const lb=$('#lb');lb.classList.remove('open');lb.hidden=false;void lb.offsetWidth;requestAnimationFrame(()=>lb.classList.add('open'));$('#lbClose').focus()}
function closeLb(){const lb=$('#lb');if(lb.hidden)return;lb.classList.remove('open');const done=()=>{lb.hidden=true;lastFocus&&lastFocus.focus()};matchMedia('(prefers-reduced-motion: reduce)').matches?done():setTimeout(done,320)}
document.addEventListener('click',e=>{const c=e.target.closest('.cert-open[data-c]');if(c){const x=D.certs[+c.dataset.c];openLb(x.img,x.title,`${x.issuer} · ${x.date}`,x.file);return}
 const v=e.target.closest('[data-xcert]');if(v){const x=D.experience[+v.dataset.xcert];openLb(x.cert.img,x.cert.title,`${x.short} · ${x.cert.date}`,x.cert.file)}});
$('#lbClose').onclick=closeLb;$('#lb').onclick=e=>{if(e.target.id==='lb')closeLb()};
addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#lb').hidden)closeLb()});

/* about page */
$('#bio').insertAdjacentHTML('beforeend',D.bio.map(p=>`<p>${p}</p>`).join(''));
/* About bio: types itself out quickly the first time it scrolls into view (tap to finish instantly) */
(()=>{const bio=$('#bio');if(!bio||matchMedia('(prefers-reduced-motion: reduce)').matches||!('IntersectionObserver' in window))return;
 const ps=[...bio.querySelectorAll('p')];const nodes=[];
 ps.forEach(p=>{const w=document.createTreeWalker(p,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode())nodes.push([n,n.nodeValue])});
 let started=false,done=false,raf=0;
 const caret=document.createElement('span');caret.className='tw-caret';caret.setAttribute('aria-hidden','true');
 const finish=()=>{if(done)return;done=true;cancelAnimationFrame(raf);nodes.forEach(([n,t])=>n.nodeValue=t);caret.remove();bio.style.minHeight='';bio.classList.remove('typing')};
 const start=()=>{if(started)return;started=true;bio.style.minHeight=bio.offsetHeight+'px';bio.classList.add('typing');
  nodes.forEach(x=>{x[1]=x[0].nodeValue;x[0].nodeValue=''});let i=0,k=0;const per=14;
  const step=()=>{let left=per;while(left>0&&i<nodes.length){const [n,t]=nodes[i];const take=Math.min(left,t.length-k);n.nodeValue=t.slice(0,k+take);k+=take;left-=take;
    if(k>=t.length){i++;k=0}}
   if(i<nodes.length){const cur=nodes[i][0];cur.parentNode.insertBefore(caret,cur.nextSibling);raf=requestAnimationFrame(step)}else{setTimeout(finish,600)}};
  raf=requestAnimationFrame(step)};
 bio.addEventListener('click',()=>{if(started)finish()});document.addEventListener('langchange',()=>{if(started)finish()});
 const io=new IntersectionObserver(es=>{if(es.some(e=>e.isIntersecting)&&ps[0].offsetParent){io.disconnect();setTimeout(start,250)}},{threshold:.25});io.observe(ps[0]);
})();
{if(IMG.tools&&!IMG.tools.CapCut){IMG.tools=Object.fromEntries(Object.entries(IMG.tools).flatMap(([k,v])=>k==='Canva'?[[k,v],['CapCut','data:image/webp;base64,']]:[[k,v]]))}
const card=(t,d)=>`<div class="tool${d?' dup':''}"${d?' aria-hidden="true"':''}><img src="${IMG.tools[t]}" alt="">${t}</div>`;const ks=Object.keys(IMG.tools);if($('#tools'))$('#tools').innerHTML=`<div class="tools-track">${ks.map(t=>card(t)).join('')}${ks.map(t=>card(t,1)).join('')}</div>`;}

/* projects */
