/* FormSubmit: one professional email format for every message sent from the site */
window.FS_FIELDS=(fd,{name,email,subject,message,source})=>{
 const when=new Date().toLocaleString('en-US',{dateStyle:'full',timeStyle:'short'});
 let tz='';try{tz=Intl.DateTimeFormat().resolvedOptions().timeZone||''}catch(_){}
 fd.append('Full Name',name);fd.append('email',email);if(subject)fd.append('Subject',subject);fd.append('Message',message);
 fd.append('Sent From',source);fd.append('Date and Time',when+(tz?' ('+tz+')':''));
 fd.append('_replyto',email);fd.append('_template','table');fd.append('_captcha','false');
 fd.append('_autoresponse','Hello '+name.split(' ')[0]+',\n\nThank you for reaching out through my portfolio. This is a confirmation that I have received your message, and I will get back to you as soon as possible, usually within one to two days.\n\nFor your reference, here is a copy of your message:\n\n"'+message+'"\n\nBest regards,\nLeonel Bulawan\nBS Computer Science, Sorsogon State University – Bulan Campus\nhttps://leonelbulawan.vercel.app\n\nThis is an automatic reply. You can respond directly to this email if you need to add anything.');
 return fd};
/* contact form */
$('#contactForm').onsubmit=async e=>{e.preventDefault();const f=e.target,n=$('#cName'),m=$('#cEmail'),sub=$('#cSubject'),t=$('#cMsg'),btn=f.querySelector('.cf-send');
 [n,m,t].forEach(el=>el.classList.remove('bad'));const miss=[];
 if(!n.value.trim()){miss.push('your name');n.classList.add('bad')}
 if(!/\S+@\S+\.\S+/.test(m.value)){miss.push('a valid email');m.classList.add('bad')}
 if(t.value.trim().length<10){miss.push('a message');t.classList.add('bad')}
 const box=$('#cfMsg');
 [n,m,t].forEach(el=>el.setAttribute('aria-invalid',el.classList.contains('bad')));
 if(miss.length){box.innerHTML=`<span style="color:#d6336c">Add ${miss.join(', ')} first.</span>`;const fb=f.querySelector('.bad');if(fb)fb.focus();return}
 if($('#cHoney').value)return;
 const subject=sub.value.trim()||'Message from your portfolio';
 const body=`${t.value.trim()}\n\n${n.value.trim()}\n${m.value.trim()}`;
 btn.disabled=true;const label=btn.textContent;btn.textContent='Sending…';box.innerHTML='';
 try{
  const fd=new FormData();
  FS_FIELDS(fd,{name:n.value.trim(),email:m.value.trim(),subject:sub.value.trim()||'(no subject)',message:t.value.trim(),source:'Contact page – leonelbulawan.vercel.app'});
  fd.append('_subject','New portfolio inquiry from '+n.value.trim()+(sub.value.trim()?' – '+sub.value.trim():''));
  // no-cors: the browser delivers the form but hides FormSubmit's reply, so a resolved request counts as sent
  await fetch('https://formsubmit.co/ajax/'+MAIL,{method:'POST',mode:'no-cors',body:fd});
  const first=esc(n.value.trim().split(' ')[0]),addr=esc(m.value.trim()),subj=esc(subject);
  f.classList.add('sent');
  box.innerHTML=`<div class="cf-success" tabindex="-1">
    <div class="cfs-icon"><svg viewBox="0 0 52 52" aria-hidden="true"><circle cx="26" cy="26" r="24"/><path d="M15 27l7 7 15-16"/></svg></div>
    <div class="cfs-body">
      <h3>Message sent successfully</h3>
      <p>Thank you, ${first}. Your message has been delivered, and I will get back to you at <b>${addr}</b> as soon as I can.</p>
      <dl class="cfs-meta"><div><dt>Subject</dt><dd>${subj}</dd></div><div><dt>Sent</dt><dd>${new Date().toLocaleString('en-PH',{dateStyle:'medium',timeStyle:'short'})}</dd></div></dl>
      <button type="button" class="btn outline cfs-again">Send another message</button>
    </div></div>`;
  f.reset();
  const card=box.querySelector('.cf-success');card.focus({preventScroll:true});card.scrollIntoView({behavior:'smooth',block:'center'});
  box.querySelector('.cfs-again').onclick=()=>{f.classList.remove('sent');box.innerHTML='';$('#cName').focus()};
 }catch(err){
  const mail=`mailto:${MAIL}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
  if(err&&err.activation){box.innerHTML=`<div class="cf-ready"><p><b>Almost there.</b> This contact form is waiting to be activated by its owner, so the message wasn't delivered yet. Please try again later, or email <b>${MAIL}</b> directly.</p></div>`;return}
  box.innerHTML=`<div class="cf-ready"><p>The message couldn't be sent from here. You can still send it from your email app, or copy it and paste it into any email to <b>${MAIL}</b>.</p><div class="acts"><a class="btn" href="${mail}">Open email app</a><button type="button" class="btn outline" id="cfCopy">Copy message</button></div></div>`;
  $('#cfCopy').onclick=()=>copyText(`To: ${MAIL}\nSubject: ${subject}\n\n${body}`,'Message copied');
 }finally{btn.disabled=false;btn.textContent=label}};

/* copy */
function copyText(v,label){(navigator.clipboard?navigator.clipboard.writeText(v):Promise.reject()).then(()=>toast(label||('Copied '+v))).catch(()=>toast('Copy blocked. Select the text and copy it manually.'))}
document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>copyText(b.dataset.copy));

/* scroll animation: items glide in when they enter the screen, from below when scrolling down and from above when scrolling up */
const RV=(()=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches||!('IntersectionObserver' in window))return {scan(){}};
 const io=new IntersectionObserver(es=>{for(const e of es){const el=e.target;
   if(e.isIntersecting){el.classList.remove('out-down','out-up')}
   else{el.classList.add(e.boundingClientRect.top<0?'out-up':'out-down');el.classList.remove(e.boundingClientRect.top<0?'out-down':'out-up')}}},{threshold:.12,rootMargin:'0px 0px -6% 0px'});
 const groups=[['.sec-head,.center-head,.filters',''],['#homeView .split .portrait,#aboutView .split .portrait','from-left'],['.split .txt','from-right'],
  ['.facts','zoom'],['.xp-card','stagger'],['.cert','stagger'],['.ab-hero > div','stagger'],['.drive','stagger'],['.tm-card','zoom'],['.tools',''],
  ['.xp .x-art','from-left'],['.xp .x-txt','from-right'],['.ci-row','stagger'],['#contactForm',''],['.contact-grid h2,.contact-grid > div > p',''],['footer .foot > div','stagger']];
 function scan(){for(const [sel,mode] of groups)document.querySelectorAll(sel).forEach((el,i)=>{if(el.classList.contains('rv'))return;
   el.classList.add('rv');if(mode&&mode!=='stagger')el.classList.add(mode);
   if(mode==='stagger'){const sib=[...el.parentElement.children].filter(c=>c.matches(sel));el.style.setProperty('--d',(Math.min(sib.indexOf(el),5)*.09)+'s')}
   const r=el.getBoundingClientRect();if(el.offsetParent&&r.top>innerHeight)el.classList.add('out-down');io.observe(el)})}
 return {scan}})();

/* splash: shows once per visit; tap, click or any key skips it. When it ends, the quote glides into place in the hero */
(()=>{const sp=$('#splash');if(!sp)return;let seen=false;try{seen=sessionStorage.getItem('splashSeen')==='1';sessionStorage.setItem('splashSeen','1')}catch(e){}
 const root=document.documentElement;
 if(seen){sp.remove();root.classList.remove('splashing');return}
 const still=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const finish=()=>{if(sp.isConnected)sp.remove();root.classList.remove('splashing')};
 if(still){sp.addEventListener('animationend',e=>{if(e.target===sp)finish()});setTimeout(finish,3600);return}
 sp.style.animation='none';let done=false;
 function handoff(){if(done)return;done=true;clearTimeout(auto);
  if(!$('#homeView').hidden)scrollTo(0,0);
  const hq=document.querySelector('.hero-quote');
  if(!hq||$('#homeView').hidden){if(hq)hq.querySelectorAll('.hq-mark,h1,figcaption').forEach(el=>el.style.opacity='');sp.classList.add('skip');sp.style.animation='';sp.addEventListener('animationend',finish,{once:true});setTimeout(finish,900);return}
  hq.classList.add('from-splash');
  // make the incoming words visible at once so the moving block is complete
  sp.querySelectorAll('.sw,.sp-mark,.sp-quote figcaption,.sp-line').forEach(el=>{el.style.animation='none';el.style.opacity='1';el.style.transform='none';el.style.filter='none'});
  sp.querySelector('.sp-line').style.width='36px';
  const pairs=[[sp.querySelector('.sp-mark'),hq.querySelector('.hq-mark')],[sp.querySelector('blockquote'),hq.querySelector('h1')],[sp.querySelector('.sp-quote figcaption'),hq.querySelector('figcaption')]];
  const targets=pairs.map(([a,b])=>{const ra=a.getBoundingClientRect(),rb=b.getBoundingClientRect();
   const fa=parseFloat(getComputedStyle(a).fontSize),fb=parseFloat(getComputedStyle(b).fontSize);
   const sc=Math.max(.4,Math.min(1.6,fb/fa));
   const dx=(rb.left+rb.width/2)-(ra.left+ra.width/2),dy=(rb.top+rb.height/2)-(ra.top+ra.height/2);
   return [a,b,`translate(${dx}px,${dy}px) scale(${sc})`]});
  sp.classList.add('handoff');sp.style.backgroundColor='rgba(18,6,38,0)';
  requestAnimationFrame(()=>{targets.forEach(([a,,t])=>{a.style.transform=t;a.style.opacity='0'});
   setTimeout(()=>{targets.forEach(([,b])=>b.style.opacity='1');root.classList.remove('splashing')},700);
   setTimeout(()=>{finish();targets.forEach(([,b])=>b.style.opacity='')},1150)})}
 hqPrep();function hqPrep(){const hq=document.querySelector('.hero-quote');if(hq){hq.classList.add('from-splash');hq.querySelectorAll('.hq-mark,h1,figcaption').forEach(el=>el.style.opacity='0')}}
 const auto=setTimeout(handoff,4300);
 sp.addEventListener('click',handoff);addEventListener('keydown',handoff,{once:true})})();

/* filters on phones: auto-flow left, pause while the visitor swipes, loop seamlessly */
(()=>{const box=$('#filters');if(!box)return;const mq=matchMedia('(max-width:860px)'),still=matchMedia('(prefers-reduced-motion: reduce)');
 let paused=false,resume=0,last=0;
 const hold=()=>{paused=true;clearTimeout(resume)},release=()=>{clearTimeout(resume);resume=setTimeout(()=>paused=false,2200)};
 box.addEventListener('pointerdown',hold);box.addEventListener('touchstart',hold,{passive:true});
 box.addEventListener('pointerup',release);box.addEventListener('touchend',release);box.addEventListener('pointercancel',release);
 box.addEventListener('mouseenter',hold);box.addEventListener('mouseleave',release);box.addEventListener('wheel',()=>{hold();release()},{passive:true});
 function loop(t){const dt=last?Math.min(t-last,50):16;last=t;
  if(mq.matches&&!still.matches&&!$('#achievementsView').hidden){const tr=box.querySelector('.f-track');if(tr){const half=tr.scrollWidth/2;
   if(!paused)box.scrollLeft+=dt*0.03;
   if(box.scrollLeft>=half)box.scrollLeft-=half;else if(box.scrollLeft<=0&&paused===false&&half>0)box.scrollLeft+=0}}
  requestAnimationFrame(loop)}
 box.addEventListener('scroll',()=>{const tr=box.querySelector('.f-track');if(!tr)return;const half=tr.scrollWidth/2;if(box.scrollLeft>=half)box.scrollLeft-=half;else if(box.scrollLeft<1&&paused)box.scrollLeft+=half},{passive:true});
 requestAnimationFrame(loop)})();

/* 4. sliding underline under the active / hovered menu item */
const moveInk=(()=>{const ink=document.querySelector('.nav-ink'),menu=$('#menu');if(!ink)return null;
 const place=a=>{if(!a){ink.style.opacity=0;return}let x=0,el=a;while(el&&el!==menu){x+=el.offsetLeft;el=el.offsetParent}ink.style.width=a.offsetWidth+'px';ink.style.transform=`translateX(${x}px)`;ink.style.opacity=1};
 const active=()=>menu.querySelector('a.on');
 menu.querySelectorAll('a').forEach(a=>{a.addEventListener('mouseenter',()=>place(a));a.addEventListener('focus',()=>place(a))});
 menu.addEventListener('mouseleave',()=>place(active()));
 addEventListener('resize',()=>place(active()));document.fonts&&document.fonts.ready.then(()=>place(active()));
 return ()=>requestAnimationFrame(()=>place(active()))})();

/* 3. count-up numbers in the facts strip */
(()=>{const still=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const nums=[...document.querySelectorAll('#facts b')];nums.forEach(b=>{if(!b.dataset.live)b.dataset.to=b.textContent.trim()});window.runFactCount=b=>{if(still||!('IntersectionObserver' in window)){b.textContent=(+b.dataset.to).toLocaleString('en-US');return}run(b)};
 if(still||!('IntersectionObserver' in window))return;
 const run=b=>{if(b.dataset.to===undefined)return;const to=+b.dataset.to,dur=to>100?1600:1000,t0=performance.now();
  const step=t=>{const p=Math.min(1,(t-t0)/dur),e=1-Math.pow(1-p,3);b.textContent=Math.round(to*e).toLocaleString('en-US');if(p<1)requestAnimationFrame(step)};requestAnimationFrame(step)};
 const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.target.dataset.to===undefined)return;if(e.isIntersecting){run(e.target)}else{e.target.textContent='0'}}),{threshold:.6});
 nums.forEach(b=>{if(b.dataset.to!==undefined)b.textContent='0';io.observe(b)})})();

/* 6. gentle 3D tilt on certificate cards and portraits (mouse only) */
(()=>{if(!matchMedia('(hover:hover) and (pointer:fine)').matches||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const max=7;
 document.addEventListener('pointermove',e=>{const el=e.target.closest('.cert,.portrait');
  document.querySelectorAll('.tilting').forEach(x=>{if(x!==el){x.classList.remove('tilting');x.style.transform=''}});
  if(!el)return;el.classList.add('tilt','tilting');const r=el.getBoundingClientRect(),px=(e.clientX-r.left)/r.width-.5,py=(e.clientY-r.top)/r.height-.5;
  el.style.transform=`perspective(900px) rotateX(${(-py*max).toFixed(2)}deg) rotateY(${(px*max).toFixed(2)}deg) translateY(-4px)`},{passive:true});
 document.addEventListener('pointerleave',()=>document.querySelectorAll('.tilting').forEach(x=>{x.classList.remove('tilting');x.style.transform=''}))})();

