 let loading=null;
 const load=()=>loading||(loading=new Promise((ok,no)=>{window.gtInit=()=>{try{new window.google.translate.TranslateElement({pageLanguage:'en',autoDisplay:false},'gtEl');ok()}catch(e){no(e)}};
  const sc=document.createElement('script');sc.src='https://translate.google.com/translate_a/element.js?cb=gtInit';sc.async=true;sc.onerror=()=>no(new Error('blocked'));document.head.appendChild(sc);setTimeout(()=>no(new Error('timeout')),6000)}));
