 let on=false,micOn=false,working=false,speaking=false,muted=false,gen=0,lastFocus=null,voice=null;
 let actx=null,stream=null,srcNode=null,proc=null,sink=null,playNode=null,raf=0,m=.1;
 const hist=[];
 try{muted=localStorage.getItem('leoMute')==='1'}catch(_){}
 const status=s=>{stEl.textContent=T(s)};
 const mode=x=>{av.classList.remove('talk','listen','think');if(x)av.classList.add(x)};
 const lang=()=>(window.I18N&&I18N.lang==='fil')?'fil':'en';
 const setMute=()=>{mute.setAttribute('aria-pressed',muted);mute.setAttribute('aria-label',T(muted?"Unmute Leo's voice":"Mute Leo's voice"))};setMute();
 const paintMic=()=>{mic.classList.toggle('on',micOn);mic.classList.toggle('rec',micOn&&!working&&!speaking);mic.setAttribute('aria-pressed',micOn);
  const l=T(micOn?'Turn off microphone':'Turn on microphone');mic.setAttribute('aria-label',l);mic.title=l};
 const idle=()=>{if(!on)return;paintMic();if(working||speaking)return;
  if(micOn){mode('listen');status('Listening…')}else{mode('');status(LIVE&&CAN_MIC?'Your microphone is off. Turn it on to talk to Leo.':'Voice calls work on the live website.')}};

 /* ---------- Leo's voice ---------- */
 const mouthLoop=()=>{let target=.1;
  if(playNode&&playNode.an){const a=playNode.an,buf=playNode.buf;a.getFloatTimeDomainData(buf);let s=0;for(let i=0;i<buf.length;i++)s+=buf[i]*buf[i];
   const rms=Math.sqrt(s/buf.length);target=rms<.012?.1:Math.min(1,.18+rms*5.5)}
  else if(speaking&&fb.on)target=fb.level();
  m+=(target-m)*.5;av.style.setProperty('--m',m.toFixed(3));
  if(!speaking&&m<.12){av.classList.remove('talk');raf=0;return}
  raf=requestAnimationFrame(mouthLoop)};
 const startMouth=()=>{mode('talk');if(!raf)raf=requestAnimationFrame(mouthLoop)};
 const b64buf=b=>{const s=atob(b),u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);return u.buffer};
 /* plays the AI voice (WAV) and moves the mouth from the real sound level */
 const playAI=async b64=>{const g=gen;const buf=await actx.decodeAudioData(b64buf(b64));if(g!==gen||!on)return;
  return new Promise(res=>{const src=actx.createBufferSource();src.buffer=buf;const an=actx.createAnalyser();an.fftSize=1024;
   src.connect(an);an.connect(actx.destination);playNode={src,an,buf:new Float32Array(an.fftSize)};
   src.onended=()=>{if(playNode&&playNode.src===src)playNode=null;res()};speaking=true;paintMic();startMouth();src.start()})};
 const stopVoice=()=>{gen++;if(playNode){try{playNode.src.onended=null;playNode.src.stop()}catch(_){}playNode=null}try{if(TTS&&(TTS.speaking||TTS.pending))TTS.cancel()}catch(_){}fb.on=false;speaking=false};
 /* backup: the device's built-in voice */
 const fb={on:false,t0:0,wS:0,wD:0,syl:1,b:false,level(){const t=performance.now();if(this.b){if(t<this.wS+this.wD){const k=(t-this.wS)/this.wD;return .25+.7*Math.abs(Math.sin(k*Math.PI*this.syl))}return .1}
  return t-this.t0>250?.3+.5*Math.abs(Math.sin(t/95))*Math.abs(Math.sin(t/41+1.3)):.1}};
 const pickVoice=()=>{if(!TTS)return null;const vs=TTS.getVoices();if(!vs.length)return null;
  if(lang()==='fil'){const f=vs.find(v=>/^(fil|tl)/i.test(v.lang));if(f)return f}
  const en=vs.filter(v=>/^en/i.test(v.lang));return en.find(v=>/en-(US|GB|PH)/i.test(v.lang)&&!/female/i.test(v.name))||en[0]||null};
 const plain=t=>t.replace(/\*\*(.+?)\*\*/g,'$1').replace(/https?:\/\/\S+/g,'the link on this website').replace(/^\s*(?:[-*•]|\d+[.)])\s+/gm,'').replace(/[–—]/g,', ').replace(/\s*\n+\s*/g,'. ').replace(/([\w.+-]+)@([\w-]+)\.([a-z]{2,})/gi,'$1 at $2 dot $3').replace(/\+63/g,'plus 63').replace(/:\s*\./g,':').replace(/\.\s*\./g,'.').trim();
 const KEEP=window.__lvU=[];
 const speakDevice=text=>new Promise(res=>{const g=gen;if(!TTS){res();return}
  const parts=plain(text).split(/(?<=[.!?])\s+/).filter(Boolean);let i=0;voice=voice||pickVoice();speaking=true;paintMic();
  const one=(txt,useV,cb)=>{let started=false,fin=false;const u=new SpeechSynthesisUtterance(txt);u.lang=useV&&voice?voice.lang:(lang()==='fil'?'fil-PH':'en-US');if(useV&&voice)u.voice=voice;u.rate=1.02;
   KEEP.push(u);if(KEEP.length>20)KEEP.shift();const end=ok=>{if(fin)return;fin=true;clearTimeout(t1);clearTimeout(t2);fb.on=false;cb(ok||started)};
   u.onstart=()=>{started=true;if(g!==gen)return;fb.on=true;fb.t0=performance.now();fb.b=false;startMouth()};
   u.onboundary=e=>{if(e.name==='sentence')return;const L=e.charLength||4;fb.b=true;fb.wS=performance.now();fb.syl=Math.max(1,Math.round(L/3));fb.wD=Math.min(900,Math.max(140,L*62))};
   u.onend=()=>end(true);u.onerror=e=>end(e&&(e.error==='interrupted'||e.error==='canceled'));
   const t1=setTimeout(()=>{if(!started){try{TTS.cancel()}catch(_){}end(false)}},3000),t2=setTimeout(()=>end(true),3000+txt.length*110);
   try{TTS.resume()}catch(_){}TTS.speak(u)};
  const next=()=>{if(g!==gen||!on){res();return}if(i>=parts.length){speaking=false;res();return}const t=parts[i++];
   one(t,true,ok=>{if(g!==gen){res();return}if(ok){setTimeout(next,60);return}voice=null;one(t,false,()=>setTimeout(next,60))})};
  next()});
