 addEventListener('keydown',e=>{if(e.key==='Escape'&&!pn.hidden)close(true)});
 document.addEventListener('pointerdown',e=>{if(!pn.hidden&&!pn.contains(e.target)&&!fab.contains(e.target)&&!e.target.closest('.dr-a11y,.hd-a11y,#langPop'))close()});
